     1|/**
     2| * InvestmentCard — the ONE canonical compact investment card for IVX.
     3| *
     4| * Used by:
     5| *   • Main/Home feed (InvestorFirstFeed) for deal blocks
     6| *   • Search results
     7| *   • Saved deals
     8| *   • Portfolio deal previews
     9| *
    10| * Visual design (owner-approved):
    11| *   Compact card with horizontal image carousel (up to 8 photos)
    12| *   Image counter pill (top-right)
    13| *   Status badge (top-left)
    14| *   Property title + location
    15| *   Investment summary panel (Sale Price, Total Investment, ROI, Timeline)
    16| *   Timeline summary (duration, current stage, completion %)
    17| *   Minimum investment / ownership row
    18| *   Category chips (Tokenized / JV Deal / Buyer)
    19| *   Developer name
    20| *   Collapsible Details section
    21| *   Action row: Like, Comment, Save, Share
    22| *   CTA buttons: View Deal + Invest Now
    23| *   NO full-screen reel layout — always a card in a scroll feed
    24| */
    25|import React, { memo, useCallback, useMemo, useState } from 'react';
    26|import {
    27|  View,
    28|  Text,
    29|  StyleSheet,
    30|  TouchableOpacity,
    31|  Share,
    32|  ScrollView,
    33|  useWindowDimensions,
    34|  LayoutAnimation,
    35|  Platform,
    36|} from 'react-native';
    37|import { Image } from 'expo-image';
    38|import * as Haptics from 'expo-haptics';
    39|import {
    40|  Heart,
    41|  MessageCircle,
    42|  Share2,
    43|  Bookmark,
    44|  MapPin,
    45|  TrendingUp,
    46|  Hexagon,
    47|  Users,
    48|  Home as HomeIcon,
    49|  ChevronRight,
    50|  ImageOff,
    51|  HardHat,
    52|  Clock,
    53|  DollarSign,
    54|  PieChart,
    55|  ChevronDown,
    56|  CheckCircle2,
    57|  AlertCircle,
    58|  Circle,
    59|} from 'lucide-react-native';
    60|import Colors from '@/constants/colors';
    61|import { formatCount, compactCurrency } from '@/lib/reel-formatters';
    62|import { formatCurrencyWithDecimals } from '@/lib/formatters';
    63|import {
    64|  type TimelineSummary,
    65|  type TimelineStage,
    66|  type TimelineStageStatus,
    67|  getTimelineStatusColor,
    68|  formatTimelineDate,
    69|} from '@/lib/timeline-stages';
    70|
    71|export interface InvestmentCardData {
    72|  dealId: string;
    73|  title: string;
    74|  location: string | null;
    75|  photos: string[];
    76|  roi: number | null;
    77|  minimumInvestment: number | null;
    78|  status: string;
    79|  category: string | null;
    80|  dealUrl: string | null;
    81|  likeCount: number;
    82|  commentCount: number;
    83|  saveCount: number;
    84|  shareCount: number;
    85|  isLiked: boolean;
    86|  isSaved: boolean;
    87|  // ── Restored old-card investment details ──
    88|  salePrice: number | null;
    89|  totalInvestment: number | null;
    90|  timelineMin: number | null;
    91|  timelineMax: number | null;
    92|  timelineUnit: 'months' | 'years' | null;
    93|  minimumOwnershipPercent: number | null;
    94|  fractionalStartAmount: number | null;
    95|  developerName: string | null;
    96|  developerLogo: string | null;
    97|  investmentDetails: string | null;
    98|  timelineSummary: TimelineSummary | null;
    99|}
   100|
   101|export interface InvestmentCardProps {
   102|  data: InvestmentCardData;
   103|  onOpenDeal: (data: InvestmentCardData) => void;
   104|  onInvest: (data: InvestmentCardData) => void;
   105|  onLike: (data: InvestmentCardData) => void;
   106|  onComment: (data: InvestmentCardData) => void;
   107|  onSave: (data: InvestmentCardData) => void;
   108|  onShare: (data: InvestmentCardData) => void;
   109|  testIDPrefix?: string;
   110|}
   111|
   112|interface CategoryChip {
   113|  id: string;
   114|  label: string;
   115|  icon: React.ReactNode;
   116|  tint: string;
   117|}
   118|
   119|function useCategoryChips(dealType: string | null | undefined): CategoryChip[] {
   120|  const t = (dealType ?? '').toLowerCase();
   121|  const tokenized: CategoryChip = {
   122|    id: 'tokenized',
   123|    label: 'Tokenized',
   124|    icon: <Hexagon size={13} color={Colors.primary} />,
   125|    tint: Colors.primary,
   126|  };
   127|  const jv: CategoryChip = {
   128|    id: 'jv',
   129|    label: 'JV Deal',
   130|    icon: <Users size={13} color={Colors.blue} />,
   131|    tint: Colors.blue,
   132|  };
   133|  const buyer: CategoryChip = {
   134|    id: 'buyer',
   135|    label: 'Buyer',
   136|    icon: <HomeIcon size={13} color={Colors.green} />,
   137|    tint: Colors.green,
   138|  };
   139|  switch (t) {
   140|    case 'jv':
   141|    case 'equity_split':
   142|    case 'hybrid':
   143|      return [tokenized, jv, buyer];
   144|    case 'development':
   145|    case 'new_construction':
   146|    case 'rehab_construction':
   147|      return [jv, tokenized, buyer];
   148|    case 'profit_sharing':
   149|      return [tokenized, buyer, jv];
   150|    default:
   151|      return [tokenized, jv, buyer];
   152|  }
   153|}
   154|
   155|/** Safe display helper — never show null/undefined/NaN. */
   156|function safeText(value: string | null | undefined, fallback = 'Not available'): string {
   157|  if (value === null || value === undefined || value === '') return fallback;
   158|  const str = String(value).trim();
   159|  if (str === '' || str === 'null' || str === 'undefined' || str === 'NaN') return fallback;
   160|  return str;
   161|}
   162|
   163|function safeNumber(value: number | null | undefined): boolean {
   164|  return value !== null && value !== undefined && Number.isFinite(value) && value > 0;
   165|}
   166|
   167|const MAX_IMAGES = 8;
   168|const CAROUSEL_HEIGHT = 240;
   169|
   170|const InvestmentCard = memo(function InvestmentCard({
   171|  data,
   172|  onOpenDeal,
   173|  onInvest,
   174|  onLike,
   175|  onComment,
   176|  onSave,
   177|  onShare,
   178|  testIDPrefix = 'investment-card',
   179|}: InvestmentCardProps) {
   180|  const { width: screenWidth } = useWindowDimensions();
   181|  const cardWidth = Math.min(screenWidth - 32, 520);
   182|
   183|  const photos = useMemo(
   184|    () => (data.photos && data.photos.length > 0 ? data.photos.slice(0, MAX_IMAGES) : []),
   185|    [data.photos],
   186|  );
   187|
   188|  const [activeIndex, setActiveIndex] = useState(0);
   189|  const [liked, setLiked] = useState(data.isLiked);
   190|  const [likeCount, setLikeCount] = useState(data.likeCount);
   191|  const [saved, setSaved] = useState(data.isSaved);
   192|  const [saveCount, setSaveCount] = useState(data.saveCount);
   193|  const [detailsExpanded, setDetailsExpanded] = useState(false);
   194|
   195|  const categoryChips = useCategoryChips(data.category);
   196|  const isActiveStatus = (data.status ?? 'published') === 'published';
   197|
   198|  const handleScroll = useCallback((event: { nativeEvent: { contentOffset: { x: number }; layoutMeasurement: { width: number } } }) => {
   199|    const x = event.nativeEvent.contentOffset.x;
   200|    const w = event.nativeEvent.layoutMeasurement.width;
   201|    if (w > 0) {
   202|      const idx = Math.round(x / w);
   203|      if (idx >= 0 && idx < photos.length && idx !== activeIndex) {
   204|        setActiveIndex(idx);
   205|        void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   206|      }
   207|    }
   208|  }, [photos.length, activeIndex]);
   209|
   210|  const handleLike = useCallback(() => {
   211|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   212|    const next = !liked;
   213|    setLiked(next);
   214|    setLikeCount((p: number) => p + (next ? 1 : -1));
   215|    onLike(data);
   216|  }, [liked, onLike, data]);
   217|
   218|  const handleSave = useCallback(() => {
   219|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   220|    const next = !saved;
   221|    setSaved(next);
   222|    setSaveCount((p: number) => p + (next ? 1 : -1));
   223|    onSave(data);
   224|  }, [saved, onSave, data]);
   225|
   226|  const handleShare = useCallback(() => {
   227|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   228|    onShare(data);
   229|  }, [onShare, data]);
   230|
   231|  const handleComment = useCallback(() => {
   232|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
   233|    onComment(data);
   234|  }, [onComment, data]);
   235|
   236|  const handleViewDeal = useCallback(() => {
   237|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
   238|    onOpenDeal(data);
   239|  }, [onOpenDeal, data]);
   240|
   241|  const handleInvestNow = useCallback(() => {
   242|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy);
   243|    onInvest(data);
   244|  }, [onInvest, data]);
   245|
   246|  const toggleDetails = useCallback(() => {
   247|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   248|    if (Platform.OS === 'android') {
   249|      LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
   250|    }
   251|    setDetailsExpanded(prev => !prev);
   252|  }, []);
   253|
   254|  // ── Investment summary values ──
   255|  const salePriceLabel = safeNumber(data.salePrice)
   256|    ? compactCurrency(data.salePrice!)
   257|    : 'Not available';
   258|
   259|  const totalInvestmentLabel = safeNumber(data.totalInvestment)
   260|    ? compactCurrency(data.totalInvestment!)
   261|    : 'Not available';
   262|
   263|  const roiLabel = safeNumber(data.roi)
   264|    ? `${data.roi}%`
   265|    : 'Not available';
   266|
   267|  const timelineLabel = useMemo(() => {
   268|    if (data.timelineSummary && data.timelineSummary.estimatedTotalDuration) {
   269|      return data.timelineSummary.estimatedTotalDuration;
   270|    }
   271|    const min = data.timelineMin;
   272|    const max = data.timelineMax;
   273|    const unit = data.timelineUnit === 'years' ? 'yr' : 'mo';
   274|    if (min && min > 0 && max && max > 0) {
   275|      return `${min}\u2013${max} ${unit}`;
   276|    }
   277|    if (max && max > 0) return `${max} ${unit}`;
   278|    if (min && min > 0) return `${min} ${unit}`;
   279|    return 'Timeline pending verification';
   280|  }, [data.timelineMin, data.timelineMax, data.timelineUnit, data.timelineSummary]);
   281|
   282|  const minInvestmentLabel = safeNumber(data.minimumInvestment)
   283|    ? `From ${formatCurrencyWithDecimals(data.minimumInvestment!)}`
   284|    : 'Not available';
   285|
   286|  const minOwnershipLabel = safeNumber(data.minimumOwnershipPercent)
   287|    ? `${data.minimumOwnershipPercent!.toFixed(4)}%`
   288|    : 'Not available';
   289|
   290|  const developerLabel = safeText(data.developerName, 'Not available');
   291|
   292|  const summaryItems = useMemo(() => [
   293|    { icon: <DollarSign size={12} color={Colors.primary} />, label: 'SALE PRICE', value: salePriceLabel },
   294|    { icon: <PieChart size={12} color={Colors.blue} />, label: 'TOTAL INVESTMENT', value: totalInvestmentLabel },
   295|    { icon: <TrendingUp size={12} color={Colors.success} />, label: 'ROI', value: roiLabel },
   296|    { icon: <Clock size={12} color={Colors.warning} />, label: 'TIMELINE', value: timelineLabel },
   297|  ], [salePriceLabel, totalInvestmentLabel, roiLabel, timelineLabel]);
   298|
   299|  return (
   300|    <View
   301|      style={[styles.container, { width: cardWidth }]}
   302|      testID={`${testIDPrefix}-${data.dealId}`}
   303|    >
   304|      {/* 1. Image Carousel */}
   305|      <View style={styles.carouselContainer}>
   306|        {photos.length > 0 ? (
   307|          <ScrollView
   308|            horizontal
   309|            pagingEnabled
   310|            showsHorizontalScrollIndicator={false}
   311|            onScroll={handleScroll}
   312|            scrollEventThrottle={16}
   313|            decelerationRate="fast"
   314|            bounces={false}
   315|            style={styles.carousel}
   316|          >
   317|            {photos.map((uri: string, i: number) => (
   318|              <View key={i} style={[styles.imageFrame, { width: cardWidth }]}>
   319|                <Image
   320|                  source={{ uri }}
   321|                  style={styles.image}
   322|                  contentFit="cover"
   323|                  transition={150}
   324|                  testID={`${testIDPrefix}-img-${i}`}
   325|                />
   326|              </View>
   327|            ))}
   328|          </ScrollView>
   329|        ) : (
   330|          <View style={[styles.noImage, { width: cardWidth }]}>
   331|            <ImageOff size={28} color={Colors.textTertiary} />
   332|            <Text style={styles.noImageText}>No photos available</Text>
   333|          </View>
   334|        )}
   335|
   336|        {/* 2. Status badge */}
   337|        <View style={styles.statusBadge}>
   338|          <View style={[styles.statusDot, { backgroundColor: isActiveStatus ? Colors.success : Colors.warning }]} />
   339|          <Text style={styles.statusText}>{isActiveStatus ? 'ACTIVE' : 'PENDING'}</Text>
   340|        </View>
   341|
   342|        {/* Image counter */}
   343|        {photos.length > 1 && (
   344|          <View style={styles.counterPill}>
   345|            <Text style={styles.counterText}>
   346|              {activeIndex + 1}/{photos.length}
   347|            </Text>
   348|          </View>
   349|        )}
   350|
   351|        {/* Pagination dots */}
   352|        {photos.length > 1 && (
   353|          <View style={styles.dotsRow}>
   354|            {photos.map((_, i) => (
   355|              <View
   356|                key={i}
   357|                style={[styles.dot, i === activeIndex && styles.dotActive]}
   358|              />
   359|            ))}
   360|          </View>
   361|        )}
   362|      </View>
   363|
   364|      {/* Card body */}
   365|      <View style={styles.body}>
   366|        {/* 3. Title + 4. Location */}
   367|        <Text style={styles.title} numberOfLines={1} testID={`${testIDPrefix}-title-${data.dealId}`}>
   368|          {data.title}
   369|        </Text>
   370|        {data.location ? (
   371|          <View style={styles.locationRow}>
   372|            <MapPin size={13} color={Colors.textSecondary} />
   373|            <Text style={styles.locationText} numberOfLines={1}>{data.location}</Text>
   374|          </View>
   375|        ) : null}
   376|
   377|        {/* 5. Main financial summary panel */}
   378|        <View style={styles.summaryPanel} testID={`${testIDPrefix}-summary-${data.dealId}`}>
   379|          {summaryItems.map((item, idx) => (
   380|            <View
   381|              key={item.label}
   382|              style={[
   383|                styles.summaryItem,
   384|                idx < summaryItems.length - 1 && styles.summaryItemBorder,
   385|              ]}
   386|            >
   387|              <View style={styles.summaryIconRow}>
   388|                {item.icon}
   389|                <Text style={styles.summaryLabel}>{item.label}</Text>
   390|              </View>
   391|              <Text style={styles.summaryValue} testID={`${testIDPrefix}-${item.label.replace(/\s/g, '-').toLowerCase()}-${data.dealId}`}>
   392|                {item.value}
   393|              </Text>
   394|            </View>
   395|          ))}
   396|        </View>
   397|
   398|        {/* 6. Timeline summary */}
   399|        {data.timelineSummary && (
   400|          <View style={styles.timelineSummaryBox} testID={`${testIDPrefix}-timeline-summary-${data.dealId}`}>
   401|            <View style={styles.timelineSummaryHeader}>
   402|              <Clock size={13} color={Colors.warning} />
   403|              <Text style={styles.timelineSummaryTitle}>Project Timeline</Text>
   404|            </View>
   405|            <View style={styles.timelineSummaryRow}>
   406|              <View style={styles.timelineSummaryItem}>
   407|                <Text style={styles.timelineSummaryLabel}>Current Stage</Text>
   408|                <Text style={styles.timelineSummaryValue} testID={`${testIDPrefix}-current-stage-${data.dealId}`}>
   409|                  {safeText(data.timelineSummary.currentStage, 'Pending')}
   410|                </Text>
   411|              </View>
   412|              <View style={styles.timelineSummaryItem}>
   413|                <Text style={styles.timelineSummaryLabel}>Progress</Text>
   414|                <Text style={styles.timelineSummaryValue} testID={`${testIDPrefix}-progress-${data.dealId}`}>
   415|                  {data.timelineSummary.completionPercentage}%
   416|                </Text>
   417|              </View>
   418|              <View style={styles.timelineSummaryItem}>
   419|                <Text style={styles.timelineSummaryLabel}>Est. Completion</Text>
   420|                <Text style={styles.timelineSummaryValue}>
   421|                  {data.timelineSummary.estimatedCompletionDate
   422|                    ? formatTimelineDate(data.timelineSummary.estimatedCompletionDate)
   423|                    : 'Not available'}
   424|                </Text>
   425|              </View>
   426|            </View>
   427|            {/* Progress bar */}
   428|            <View style={styles.progressBarContainer} testID={`${testIDPrefix}-progress-bar-${data.dealId}`}>
   429|              <View style={[styles.progressBarFill, { width: `${Math.min(100, Math.max(0, data.timelineSummary.completionPercentage))}%` }]} />
   430|            </View>
   431|          </View>
   432|        )}
   433|
   434|        {/* 7. Minimum investment / ownership */}
   435|        <View style={styles.minInvestRow} testID={`${testIDPrefix}-min-invest-${data.dealId}`}>
   436|          <View style={styles.minInvestItem}>
   437|            <Text style={styles.minInvestLabel}>MINIMUM INVESTMENT</Text>
   438|            <Text style={styles.minInvestValue}>{minInvestmentLabel}</Text>
   439|          </View>
   440|          <View style={styles.minInvestDivider} />
   441|          <View style={styles.minInvestItem}>
   442|            <Text style={styles.minInvestLabel}>MINIMUM OWNERSHIP</Text>
   443|            <Text style={styles.minInvestValue} testID={`${testIDPrefix}-min-ownership-${data.dealId}`}>{minOwnershipLabel}</Text>
   444|          </View>
   445|        </View>
   446|
   447|        {/* 8. Categories */}
   448|        <View style={styles.chipsRow}>
   449|          {categoryChips.map((chip) => (
   450|            <View key={chip.id} style={[styles.chip, { borderColor: `${chip.tint}44` }]}>
   451|              {chip.icon}
   452|              <Text style={[styles.chipLabel, { color: chip.tint }]}>{chip.label}</Text>
   453|            </View>
   454|          ))}
   455|        </View>
   456|
   457|        {/* 9. Developer */}
   458|        <View style={styles.developerRow} testID={`${testIDPrefix}-developer-${data.dealId}`}>
   459|          <HardHat size={13} color={Colors.primary} />
   460|          <Text style={styles.developerText} numberOfLines={1}>
   461|            Developed by <Text style={styles.developerBold}>{developerLabel}</Text>
   462|          </Text>
   463|        </View>
   464|
   465|        {/* 10. Details button */}
   466|        <TouchableOpacity
   467|          style={styles.detailsBtn}
   468|          onPress={toggleDetails}
   469|          activeOpacity={0.85}
   470|          testID={`${testIDPrefix}-details-${data.dealId}`}
   471|        >
   472|          <Text style={styles.detailsBtnText}>Details</Text>
   473|          <ChevronDown
   474|            size={16}
   475|            color={Colors.textSecondary}
   476|            style={detailsExpanded ? styles.chevronRotated : undefined}
   477|          />
   478|        </TouchableOpacity>
   479|
   480|        {/* Collapsible details section */}
   481|        {detailsExpanded && (
   482|          <View style={styles.detailsSection} testID={`${testIDPrefix}-details-section-${data.dealId}`}>
   483|            {data.investmentDetails ? (
   484|              <Text style={styles.detailsText}>{data.investmentDetails}</Text>
   485|            ) : (
   486|              <Text style={styles.detailsText}>Investment details pending verification.</Text>
   487|            )}
   488|
   489|            {/* Full timeline stages */}
   490|            {data.timelineSummary && data.timelineSummary.stages.length > 0 && (
   491|              <View style={styles.stagesContainer} testID={`${testIDPrefix}-stages-${data.dealId}`}>
   492|                <Text style={styles.stagesTitle}>Timeline Stages</Text>
   493|                {data.timelineSummary.stages.map((stage: TimelineStage, idx: number) => (
   494|                  <View key={stage.id} style={styles.stageRow}>
   495|                    <View style={styles.stageIconCol}>
   496|                      {stage.status === 'COMPLETE' ? (
   497|                        <CheckCircle2 size={16} color={getTimelineStatusColor('COMPLETE')} />
   498|                      ) : stage.status === 'ACTIVE' ? (
   499|                        <AlertCircle size={16} color={getTimelineStatusColor('ACTIVE')} />
   500|                      ) : stage.status === 'DELAYED' ? (
   501|                        <AlertCircle size={16} color={getTimelineStatusColor('DELAYED')} />
   502|                      ) : (
   503|                        <Circle size={16} color={getTimelineStatusColor('UPCOMING')} />
   504|                      )}
   505|                      {idx < data.timelineSummary!.stages.length - 1 && (
   506|                        <View style={styles.stageConnector} />
   507|                      )}
   508|                    </View>
   509|                    <View style={styles.stageContent}>
   510|                      <Text style={styles.stageName}>{stage.name}</Text>
   511|                      <View style={styles.stageStatusRow}>
   512|                        <View style={[styles.stageStatusBadge, { backgroundColor: getTimelineStatusColor(stage.status) + '22' }]}>
   513|                          <Text style={[styles.stageStatusText, { color: getTimelineStatusColor(stage.status) }]}>
   514|                            {stage.status}
   515|                          </Text>
   516|                        </View>
   517|                        {stage.percentComplete > 0 && stage.status !== 'COMPLETE' && (
   518|                          <Text style={styles.stagePercent}>{stage.percentComplete}%</Text>
   519|                        )}
   520|                      </View>
   521|                      <Text style={stage.startDate ? styles.stageDate : styles.stageDatePending}>
   522|                        Start: {formatTimelineDate(stage.startDate)}
   523|                      </Text>
   524|                      <Text style={stage.estimatedCompletionDate ? styles.stageDate : styles.stageDatePending}>
   525|                        Est. Completion: {formatTimelineDate(stage.estimatedCompletionDate)}
   526|                      </Text>
   527|                      {stage.actualCompletionDate && (
   528|                        <Text style={styles.stageDateActual}>
   529|                          Completed: {formatTimelineDate(stage.actualCompletionDate)}
   530|                        </Text>
   531|                      )}
   532|                      {stage.note && (
   533|                        <Text style={styles.stageNote}>{stage.note}</Text>
   534|                      )}
   535|                    </View>
   536|                  </View>
   537|                ))}
   538|              </View>
   539|            )}
   540|          </View>
   541|        )}
   542|
   543|        {/* 11. View Deal + 12. Invest Now */}
   544|        <View style={styles.ctaRow}>
   545|          <TouchableOpacity
   546|            style={styles.viewDealBtn}
   547|            onPress={handleViewDeal}
   548|            activeOpacity={0.85}
   549|            testID={`${testIDPrefix}-view-deal-${data.dealId}`}
   550|          >
   551|            <Text style={styles.viewDealText}>View Deal</Text>
   552|            <ChevronRight size={16} color={Colors.primary} />
